window.GCAM_DIAGRAMS = {"hero": {"title": "The crowd system", "caption": "People choose where to go; space limits how fast they can; their movement builds density; density feeds back on speed and on risk. Data and models support the people who manage it.", "nodes": [{"id": "ppl", "label": "People", "sub": "goals, speed, groups, behaviour", "x": 140, "y": 90, "w": 200, "h": 64, "sys": "economy", "detail": {"1": "Each person wants to get somewhere, at their own speed, often with friends or family. How they behave depends on what they see, know and expect.", "2": "Desired speed (about 1.34 m/s on average, Weidmann), body size, groups, route choice and information. Behaviour is social, not 'panic': people help each other far more than they push.", "3": "Research angle: profile the crowd (age, culture, familiarity, groups). At the Hajj, many pilgrims are older, walk in national groups and may not read the signs' language."}}, {"id": "spc", "label": "Space and design", "sub": "width, layout, gates, stairs", "x": 140, "y": 260, "w": 200, "h": 64, "sys": "land", "detail": {"1": "Corridors, doors, stairs and squares decide how much room people have and where they squeeze together.", "2": "Width sets capacity: flow per metre of width (specific flow) times width. The narrowest point on a route, the bottleneck, sets the flow of the whole route.", "3": "Research angle: geometry is the strongest lever. Compare designs (one-way streets, wider ramps, holding areas) in simulation before building."}}, {"id": "mov", "label": "Movement", "sub": "speed, flow, routes", "x": 450, "y": 90, "w": 200, "h": 64, "sys": "energy", "detail": {"1": "People walk, queue and turn. How many pass a line each second is the flow.", "2": "Flow = density × speed (per metre of width). Speed falls as density rises, so flow peaks near 1.2 to 1.6 people per metre per second, then falls: the fundamental diagram.", "3": "Research angle: measure the fundamental diagram for your crowd; it varies with culture, purpose and direction of flow, so imported values can mislead."}}, {"id": "den", "label": "Density and pressure", "sub": "people per m², crowd pressure", "x": 450, "y": 260, "w": 200, "h": 64, "sys": "climate", "detail": {"1": "When more people arrive than can leave, they pack closer together: density rises.", "2": "Above about 4 to 5 people per m², people touch and are pushed; near 6 to 7 or more, forces pass through bodies and crowd turbulence can start (Helbing et al. 2007).", "3": "Research angle: crowd pressure = density × variance of velocity, measurable from video, gives an early warning before a crush."}}, {"id": "dat", "label": "Sensing and data", "sub": "counts, video, phones", "x": 140, "y": 430, "w": 200, "h": 64, "sys": "water", "detail": {"1": "Counting people, cameras and phone signals tell us how full a place is and how fast people move.", "2": "Trajectories from video (for example Jülich experiments), counts at gates, and density maps from crowd-counting networks give density, speed and flow.", "3": "Research angle: pair computer-vision counts with ground truth, report errors, and handle privacy and consent for mass-gathering video."}}, {"id": "mdl", "label": "Models", "sub": "macro, cellular, social force", "x": 450, "y": 430, "w": 200, "h": 64, "sys": "neutral", "detail": {"1": "A model is a what-if machine for crowds: change the layout or the timing and see what happens.", "2": "Macroscopic (fluid-like), cellular automata (grid hops), social force (pushes and pulls) and velocity models. Each must be calibrated and validated against data.", "3": "Research angle: choose the model for the question, test sensitivity, and never trust a simulation that has not reproduced a fundamental diagram and a bottleneck flow."}}, {"id": "mgt", "label": "Management", "sub": "information, stewards, scheduling", "x": 770, "y": 175, "w": 200, "h": 64, "sys": "policy", "detail": {"1": "Organisers guide crowds with signs, announcements, stewards, barriers and timetables.", "2": "Design, Information and Management across Ingress, Circulation and Egress (Still's DIM-ICE). Tools: one-way routing, metering at gates, holding areas, scheduling.", "3": "Research angle: evaluate interventions such as Hajj group scheduling or gate metering with data and simulation, including unintended effects."}}, {"id": "out", "label": "Safety outcome", "sub": "comfort, delay, risk", "x": 770, "y": 380, "w": 200, "h": 64, "sys": "climate", "detail": {"1": "In the end we care whether people are comfortable, on time and safe.", "2": "Level of service (Fruin's A to F), waiting and egress times, and the share of time and space above critical density.", "3": "Research angle: define outcome measures before running a study, and report risk exposure (person-minutes above a density threshold), not only averages."}}], "edges": [{"from": "ppl", "to": "mov", "label": "goals, speed"}, {"from": "spc", "to": "mov", "label": "width, layout"}, {"from": "mov", "to": "den", "label": "builds up"}, {"from": "den", "to": "mov", "label": "slows down", "sys": "climate"}, {"from": "den", "to": "out", "label": "pressure, risk"}, {"from": "dat", "to": "mdl", "label": "calibrate"}, {"from": "dat", "to": "den", "label": "measure"}, {"from": "mdl", "to": "mgt", "label": "what-if"}, {"from": "mgt", "to": "ppl", "label": "information"}, {"from": "mgt", "to": "spc", "label": "gates, barriers", "sys": "policy"}], "tour": [{"focus": ["ppl"], "text": "Start with people: where they want to go, how fast they walk, and who they walk with."}, {"focus": ["ppl", "spc", "mov"], "edges": [["ppl", "mov"], ["spc", "mov"]], "text": "Their goals and the space available together decide how they move: speed, flow and routes."}, {"focus": ["mov", "den"], "edges": [["mov", "den"], ["den", "mov"]], "text": "Where more arrive than can leave, density builds. Higher density slows everyone down: a feedback loop."}, {"focus": ["den", "out"], "edges": [["den", "out"]], "text": "At very high density, pressure passes through bodies. That is when crowds become dangerous."}, {"focus": ["dat", "mdl", "den"], "edges": [["dat", "mdl"], ["dat", "den"]], "text": "Sensors measure density and flow; models, calibrated on data, test what-if questions."}, {"focus": ["mgt", "ppl", "spc"], "edges": [["mdl", "mgt"], ["mgt", "ppl"], ["mgt", "spc"]], "text": "Managers act through information, gates, barriers and timing to keep density below critical levels."}]}, "m1.1": {"title": "A crowd as a system", "caption": "People arrive, wait if they must, move through the space and leave. Space and management decide whether this stays comfortable or becomes dangerous.", "nodes": [{"id": "arr", "label": "Arrivals", "sub": "people per minute", "x": 120, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "How many people come, and when. Arrivals usually peak just before a start time or just after a train arrives."}, {"id": "gate", "label": "Gates and routes", "sub": "how many can pass", "x": 410, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "Every gate, door, stair and street has a capacity: the most people it can pass per minute."}, {"id": "wait", "label": "Waiting crowd", "sub": "the stock", "x": 410, "y": 280, "w": 170, "h": 64, "sys": "climate", "detail": "If arrivals exceed capacity, the extra people wait. The waiting crowd is a stock: it grows while arrivals exceed capacity, and shrinks afterwards."}, {"id": "space", "label": "Available space", "sub": "m² for the waiting crowd", "x": 120, "y": 280, "w": 170, "h": 64, "sys": "land", "detail": "The same number of people is comfortable in a big forecourt and dangerous in a narrow alley. Density = people ÷ area."}, {"id": "phase", "label": "Event phases", "sub": "ingress, circulation, egress", "x": 730, "y": 110, "w": 170, "h": 64, "sys": "policy", "detail": "Arriving (ingress), moving around inside (circulation) and leaving (egress). Each has its own peaks and risks."}, {"id": "mgr", "label": "Managers", "sub": "information, stewards, timing", "x": 730, "y": 280, "w": 170, "h": 64, "sys": "policy", "detail": "Organisers can change arrivals (tickets, timing), capacity (gates, routes) and information (signs, announcements)."}, {"id": "out", "label": "Outcome", "sub": "comfort or crush", "x": 410, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "Low density means comfort. Very high density means people cannot move freely, pressure builds and a crush becomes possible."}], "edges": [{"from": "arr", "to": "gate", "label": "demand"}, {"from": "gate", "to": "wait", "label": "too slow?"}, {"from": "space", "to": "wait", "label": "how dense"}, {"from": "wait", "to": "out", "label": "density"}, {"from": "phase", "to": "arr", "label": "peaks", "sys": "policy"}, {"from": "mgr", "to": "gate", "label": "opens, meters", "sys": "policy"}, {"from": "mgr", "to": "wait", "label": "informs", "sys": "policy"}], "tour": [{"focus": ["arr"], "text": "It starts with people arriving. They rarely come evenly: they bunch before kick-off or after a train."}, {"focus": ["arr", "gate"], "text": "Every gate and route can pass only so many people a minute: its capacity.", "edges": [["arr", "gate"]]}, {"focus": ["gate", "wait"], "text": "If arrivals beat capacity, the extra people wait. The waiting crowd grows like water in a bath.", "edges": [["gate", "wait"]]}, {"focus": ["space", "wait", "out"], "text": "Whether waiting is safe depends on space. Density, people per square metre, is what turns comfort into danger.", "edges": [["space", "wait"], ["wait", "out"]]}, {"focus": ["phase", "mgr"], "text": "Organisers plan each phase, arrival, circulation and departure, and manage gates, timing and information.", "edges": [["phase", "arr"], ["mgr", "gate"], ["mgr", "wait"]]}]}, "m1.2": {"title": "From a count to a level of service", "caption": "Density = people ÷ area. Space per person is its inverse. Levels of service grade space per person from A to F.", "nodes": [{"id": "cnt", "label": "Count", "sub": "people in the area", "x": 120, "y": 100, "w": 170, "h": 64, "sys": "water", "detail": "Count everyone inside a known area, from the ground, a photo or a sensor."}, {"id": "area", "label": "Area", "sub": "usable m²", "x": 120, "y": 270, "w": 170, "h": 64, "sys": "land", "detail": "Use the area people can actually stand or walk in: subtract barriers, columns and stalls."}, {"id": "dens", "label": "Density", "sub": "people per m²", "x": 430, "y": 185, "w": 170, "h": 64, "sys": "economy", "detail": "Density ρ = count ÷ area. One person per m² is comfortable walking; six or more is dangerous."}, {"id": "spp", "label": "Space per person", "sub": "m² each = 1 ÷ density", "x": 430, "y": 360, "w": 170, "h": 64, "sys": "land", "detail": "The inverse of density. Fruin's grades use space per person."}, {"id": "los", "label": "Level of service", "sub": "A (free) to F (breakdown)", "x": 760, "y": 185, "w": 170, "h": 64, "sys": "policy", "detail": "Walkway levels (Fruin 1971): A more than 3.25 m² each, B 2.3–3.25, C 1.4–2.3, D 0.9–1.4, E 0.5–0.9, F under 0.5."}, {"id": "cap", "label": "Holding capacity", "sub": "people = area × density", "x": 760, "y": 360, "w": 170, "h": 64, "sys": "climate", "detail": "To find how many fit at a comfort level, multiply the usable area by the density you accept."}], "edges": [{"from": "cnt", "to": "dens", "label": "÷ area"}, {"from": "area", "to": "dens", "label": ""}, {"from": "dens", "to": "spp", "label": "invert"}, {"from": "spp", "to": "los", "label": "grade"}, {"from": "dens", "to": "los", "label": ""}, {"from": "area", "to": "cap", "label": "× density"}, {"from": "los", "to": "cap", "label": "choose a grade", "sys": "policy"}], "tour": [{"focus": ["cnt", "area"], "text": "Start with a count and an area. Use only the area people can really use."}, {"focus": ["dens"], "text": "Density is the count divided by the area: people per square metre.", "edges": [["cnt", "dens"], ["area", "dens"]]}, {"focus": ["spp"], "text": "Turn it upside down for the space each person has.", "edges": [["dens", "spp"]]}, {"focus": ["los"], "text": "Fruin graded that space from A to F. A is free walking; F is where flow breaks down.", "edges": [["spp", "los"]]}, {"focus": ["cap", "area", "los"], "text": "Planners run it backwards: choose a grade, then area × density tells you how many people fit.", "edges": [["area", "cap"], ["los", "cap"]]}]}, "m1.3": {"title": "Density, speed and flow", "caption": "More people slow everyone down; flow is their product, so it rises, peaks at capacity and falls.", "nodes": [{"id": "rho", "label": "Density", "sub": "people per m²", "x": 130, "y": 130, "w": 170, "h": 64, "sys": "economy", "detail": "How packed the corridor is."}, {"id": "v", "label": "Speed", "sub": "m/s, falls as density rises", "x": 130, "y": 340, "w": 170, "h": 64, "sys": "energy", "detail": "Free speed about 1.34 m/s (Weidmann). Speed falls as people get in each other's way, reaching zero at about 5.4 per m² in Weidmann's curve."}, {"id": "j", "label": "Flow", "sub": "per m of width per s", "x": 450, "y": 235, "w": 170, "h": 64, "sys": "energy", "detail": "Specific flow J = ρ × v, people per metre of width per second. Total flow = J × width."}, {"id": "cap", "label": "Capacity", "sub": "max flow ≈ 1.2 per m per s", "x": 770, "y": 120, "w": 170, "h": 64, "sys": "climate", "detail": "Weidmann's curve peaks at about 1.22 people per metre per second, at about 1.75 per m². Measured values range roughly from 1.2 to over 1.6."}, {"id": "cong", "label": "Congested branch", "sub": "more people, less flow", "x": 770, "y": 340, "w": 170, "h": 64, "sys": "climate", "detail": "Right of the peak, adding people lowers flow. A congested corridor moves fewer people than a busy but free one."}, {"id": "var", "label": "Varies by crowd", "sub": "culture, purpose, direction", "x": 450, "y": 445, "w": 170, "h": 64, "sys": "water", "detail": "Fundamental diagrams differ by country, age, purpose, and between one-way and two-way flows. Measure your own crowd where possible."}], "edges": [{"from": "rho", "to": "j", "label": "×"}, {"from": "v", "to": "j", "label": "×"}, {"from": "rho", "to": "v", "label": "slows"}, {"from": "j", "to": "cap", "label": "peaks at"}, {"from": "j", "to": "cong", "label": "then falls"}, {"from": "var", "to": "v", "label": "shifts curve", "sys": "water"}], "tour": [{"focus": ["rho", "v"], "text": "Two things change when you add people: density goes up and speed goes down.", "edges": [["rho", "v"]]}, {"focus": ["j"], "text": "Flow is their product: people per metre of width per second.", "edges": [["rho", "j"], ["v", "j"]]}, {"focus": ["cap"], "text": "At first flow rises, then it peaks. That peak is the capacity, about 1.2 per metre per second in Weidmann's curve.", "edges": [["j", "cap"]]}, {"focus": ["cong"], "text": "Past the peak, more people means less flow: congestion.", "edges": [["j", "cong"]]}, {"focus": ["var"], "text": "The exact curve depends on who is walking and why. Measure your own crowd.", "edges": [["var", "v"]]}]}, "m1.4": {"title": "A route is only as wide as its narrowest point", "caption": "Demand meets the bottleneck's capacity. The difference becomes a queue upstream.", "nodes": [{"id": "dem", "label": "Demand", "sub": "people arriving per s", "x": 120, "y": 120, "w": 170, "h": 64, "sys": "economy", "detail": "How many people want to pass each second."}, {"id": "rt", "label": "Wide route", "sub": "plenty of capacity", "x": 120, "y": 320, "w": 170, "h": 64, "sys": "land", "detail": "Upstream the route is wide; its capacity is not the limit."}, {"id": "bn", "label": "Bottleneck", "sub": "narrowest point", "x": 440, "y": 220, "w": 170, "h": 64, "sys": "land", "detail": "A door, gate, stair, ramp or a narrowing street. Its width sets the route's capacity."}, {"id": "cap", "label": "Capacity", "sub": "width × specific flow", "x": 760, "y": 120, "w": 170, "h": 64, "sys": "energy", "detail": "Capacity ≈ b × Js, with Js about 1.3 to 1.9 per m per s in experiments (Seyfried et al. 2009). Planning guidance often uses lower values."}, {"id": "q", "label": "Queue", "sub": "grows at demand − capacity", "x": 440, "y": 420, "w": 170, "h": 64, "sys": "climate", "detail": "If demand exceeds capacity, the queue grows by the difference every second. Its density rises at the back of the bottleneck."}, {"id": "zip", "label": "Zipper effect", "sub": "interleaved lanes", "x": 760, "y": 330, "w": 170, "h": 64, "sys": "energy", "detail": "Inside a bottleneck people form overlapping lanes like a zipper (Hoogendoorn and Daamen 2005), which uses the width efficiently."}], "edges": [{"from": "dem", "to": "bn", "label": "arrive"}, {"from": "rt", "to": "bn", "label": "feeds"}, {"from": "bn", "to": "cap", "label": "limits"}, {"from": "dem", "to": "q", "label": "excess"}, {"from": "cap", "to": "q", "label": "drains"}, {"from": "bn", "to": "zip", "label": "inside"}], "tour": [{"focus": ["dem", "rt"], "text": "People arrive along a wide route: no problem yet."}, {"focus": ["bn"], "text": "Then the route narrows. The narrowest point is the bottleneck.", "edges": [["rt", "bn"], ["dem", "bn"]]}, {"focus": ["cap"], "text": "Its capacity is roughly width × specific flow.", "edges": [["bn", "cap"]]}, {"focus": ["q"], "text": "If more arrive than it can pass, the excess queues and the queue grows every second.", "edges": [["dem", "q"], ["cap", "q"]]}, {"focus": ["zip"], "text": "Inside the bottleneck, people interleave like a zipper.", "edges": [["bn", "zip"]]}]}, "m1.5": {"title": "Local rules, global patterns", "caption": "Each person follows simple rules about neighbours. Together they create lanes, turn-taking and waves that nobody planned.", "nodes": [{"id": "rule", "label": "Local rules", "sub": "avoid, follow, fill gaps", "x": 130, "y": 120, "w": 170, "h": 64, "sys": "economy", "detail": "Each person reacts only to those close by: keep distance, step aside from oncoming people, follow someone heading your way."}, {"id": "lane", "label": "Lane formation", "sub": "counterflow sorts itself", "x": 450, "y": 100, "w": 170, "h": 64, "sys": "energy", "detail": "In two-way corridors people end up in lanes of uniform direction. Lanes reduce conflicts and raise flow."}, {"id": "osc", "label": "Oscillations", "sub": "turn-taking at doors", "x": 450, "y": 250, "w": 170, "h": 64, "sys": "energy", "detail": "At a narrow door used both ways, small groups pass in alternating bursts, as pressure builds on one side then the other."}, {"id": "sag", "label": "Stop-and-go waves", "sub": "high density warning", "x": 450, "y": 410, "w": 170, "h": 64, "sys": "climate", "detail": "Near capacity, small slowdowns grow into waves moving backwards through the crowd (Helbing et al. 2007 observed them at the Jamarat Bridge)."}, {"id": "good", "label": "Helpful", "sub": "more flow, fewer conflicts", "x": 770, "y": 160, "w": 170, "h": 64, "sys": "policy", "detail": "Lanes and zipper effects make better use of space. Designers can encourage them, for example with a central divider."}, {"id": "bad", "label": "Warning signs", "sub": "near capacity", "x": 770, "y": 360, "w": 170, "h": 64, "sys": "climate", "detail": "Stop-and-go waves and crowd turbulence warn that density is too high: time to reduce inflow."}], "edges": [{"from": "rule", "to": "lane", "label": ""}, {"from": "rule", "to": "osc", "label": ""}, {"from": "rule", "to": "sag", "label": ""}, {"from": "lane", "to": "good", "label": "raises flow"}, {"from": "osc", "to": "good", "label": ""}, {"from": "sag", "to": "bad", "label": "danger"}], "tour": [{"focus": ["rule"], "text": "Every pattern starts with simple local rules: keep distance, step aside, follow someone going your way."}, {"focus": ["lane"], "text": "In two-way flow, these rules sort the crowd into lanes.", "edges": [["rule", "lane"]]}, {"focus": ["osc"], "text": "At narrow doors, the two directions take turns.", "edges": [["rule", "osc"]]}, {"focus": ["sag"], "text": "At high density, slowdowns grow into stop-and-go waves.", "edges": [["rule", "sag"]]}, {"focus": ["good", "bad"], "text": "Some patterns help the flow; others warn that density is too high.", "edges": [["lane", "good"], ["sag", "bad"]]}]}, "m1.6": {"title": "What shapes how people move", "caption": "Goals, habits, groups and information shape choices; those choices shape the flow.", "nodes": [{"id": "goal", "label": "Goals", "sub": "where and how fast", "x": 130, "y": 100, "w": 170, "h": 64, "sys": "economy", "detail": "Destination, urgency and desired speed differ: commuters hurry, families stroll, pilgrims follow a ritual sequence."}, {"id": "hab", "label": "Habits and familiarity", "sub": "known routes first", "x": 130, "y": 260, "w": 170, "h": 64, "sys": "economy", "detail": "People prefer routes and exits they know, often the one they arrived by (affiliation; Sime 1985)."}, {"id": "grp", "label": "Groups", "sub": "move together", "x": 130, "y": 420, "w": 170, "h": 64, "sys": "economy", "detail": "Most people at events are in groups. Groups walk at the pace of the slowest member and do not split easily."}, {"id": "info", "label": "Information", "sub": "signs, announcements, stewards", "x": 470, "y": 100, "w": 170, "h": 64, "sys": "policy", "detail": "Clear, early, trusted information shortens decision times and spreads people across routes."}, {"id": "ch", "label": "Choices", "sub": "route, exit, timing", "x": 470, "y": 260, "w": 170, "h": 64, "sys": "energy", "detail": "Decisions about which way, which exit and when to move. Their sum is the crowd's distribution across routes."}, {"id": "id", "label": "Shared identity", "sub": "helping, not panic", "x": 470, "y": 420, "w": 170, "h": 64, "sys": "economy", "detail": "In emergencies people often develop a shared identity and help each other (Drury, Cocking and Reicher 2009)."}, {"id": "flow", "label": "Crowd outcome", "sub": "queues, times, risk", "x": 780, "y": 260, "w": 170, "h": 64, "sys": "climate", "detail": "Uneven use of exits, long pre-movement times and counterflows lengthen evacuations and create hot spots."}], "edges": [{"from": "goal", "to": "ch", "label": ""}, {"from": "hab", "to": "ch", "label": "bias"}, {"from": "grp", "to": "ch", "label": "slows, sticks"}, {"from": "info", "to": "ch", "label": "steers", "sys": "policy"}, {"from": "id", "to": "ch", "label": "cooperation"}, {"from": "ch", "to": "flow", "label": "adds up to"}], "tour": [{"focus": ["goal", "hab", "grp"], "text": "People bring goals, habits and companions with them."}, {"focus": ["ch"], "text": "These shape their choices: which route, which exit, when to move.", "edges": [["goal", "ch"], ["hab", "ch"], ["grp", "ch"]]}, {"focus": ["info"], "text": "Information steers those choices, if it is clear, early and trusted.", "edges": [["info", "ch"]]}, {"focus": ["id"], "text": "In emergencies, shared identity usually makes people cooperate rather than panic.", "edges": [["id", "ch"]]}, {"focus": ["flow"], "text": "Add the choices up and you get the crowd's outcome: queues, times and risk.", "edges": [["ch", "flow"]]}]}, "m1.7": {"title": "The chain to a crowd crush", "caption": "High density removes control; forces add up; turbulence and falls follow. Each link is a chance to intervene.", "nodes": [{"id": "dem", "label": "Demand above capacity", "sub": "too many, too fast", "x": 120, "y": 100, "w": 170, "h": 64, "sys": "economy", "detail": "More people arrive than routes and spaces can handle, often because flows meet or an exit is blocked."}, {"id": "den", "label": "High density", "sub": "above about 5–6 per m²", "x": 400, "y": 100, "w": 170, "h": 64, "sys": "climate", "detail": "People touch on all sides and cannot move independently. Space per person is under about 0.2 m²."}, {"id": "force", "label": "Forces add up", "sub": "through bodies", "x": 680, "y": 100, "w": 170, "h": 64, "sys": "climate", "detail": "Pushing from many people adds up along chains of bodies. Barriers and walls concentrate it. Breathing becomes difficult."}, {"id": "turb", "label": "Crowd turbulence", "sub": "random-looking surges", "x": 680, "y": 280, "w": 170, "h": 64, "sys": "climate", "detail": "Irregular motion in all directions, people displaced several metres (Helbing et al. 2007). Crowd pressure ρ·Var(V) is high."}, {"id": "fall", "label": "Falls and collapse", "sub": "progressive", "x": 680, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "When people fall, others are pushed over them; a crowd collapse spreads. Victims die mostly of compressive asphyxia."}, {"id": "warn", "label": "Warning signs", "sub": "stop-and-go, surges, calls", "x": 400, "y": 300, "w": 170, "h": 64, "sys": "water", "detail": "Stop-and-go waves, swaying surges, people climbing out, distress calls. At Itaewon, emergency calls started hours before the crush."}, {"id": "act", "label": "Intervene early", "sub": "stop inflow, relieve, inform", "x": 120, "y": 300, "w": 170, "h": 64, "sys": "policy", "detail": "Stop or meter inflow, open relief routes, separate flows, inform those at the back. The earlier, the easier."}], "edges": [{"from": "dem", "to": "den", "label": "accumulates"}, {"from": "den", "to": "force", "label": "contact"}, {"from": "force", "to": "turb", "label": ""}, {"from": "turb", "to": "fall", "label": ""}, {"from": "den", "to": "warn", "label": "shows as"}, {"from": "warn", "to": "act", "label": "triggers", "sys": "policy"}, {"from": "act", "to": "dem", "label": "reduces", "sys": "policy"}], "tour": [{"focus": ["dem", "den"], "text": "It starts when more people arrive than the space can pass, and density climbs.", "edges": [["dem", "den"]]}, {"focus": ["force"], "text": "Above about 5 to 6 per m², people lose control of their movement and forces add up through bodies.", "edges": [["den", "force"]]}, {"focus": ["turb", "fall"], "text": "Then crowd turbulence: surges that push people over. Falls spread into a collapse.", "edges": [["force", "turb"], ["turb", "fall"]]}, {"focus": ["warn"], "text": "There are warning signs along the way: stop-and-go waves, surges, distress calls.", "edges": [["den", "warn"]]}, {"focus": ["act"], "text": "Each sign is a chance to act: stop inflow, open relief routes, inform the crowd.", "edges": [["warn", "act"], ["act", "dem"]]}]}, "m1.8": {"title": "From risk analysis to exit widths", "caption": "DIM-ICE and RAMP find where risk lies; flow rates and times size the spaces; management measures keep density down on the day.", "nodes": [{"id": "dim", "label": "DIM-ICE", "sub": "design · information · management", "x": 140, "y": 110, "w": 170, "h": 64, "sys": "policy", "detail": "Still's matrix: Design, Information, Management across Ingress, Circulation, Egress. Nine questions for every event (Still 2014)."}, {"id": "ramp", "label": "RAMP", "sub": "routes · areas · movement · profile", "x": 140, "y": 290, "w": 170, "h": 64, "sys": "policy", "detail": "Routes people take, the areas they use, movement over time, and the profile of the crowd (age, culture, familiarity)."}, {"id": "rate", "label": "Flow rates", "sub": "82 level, 66 stepped per m per min", "x": 460, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Green Guide (6th edition) planning rates for sports grounds, in people per metre width per minute."}, {"id": "time", "label": "Target times", "sub": "egress up to 8 min", "x": 460, "y": 290, "w": 170, "h": 64, "sys": "climate", "detail": "The Green Guide sets egress times of up to 8 minutes, shorter where fire risk is higher."}, {"id": "width", "label": "Exit width", "sub": "people ÷ (rate × time)", "x": 780, "y": 200, "w": 170, "h": 64, "sys": "land", "detail": "Example: 6,000 people, level route, 8 minutes: 6,000 ÷ (82 × 8) ≈ 9.1 m of exit width."}, {"id": "ops", "label": "On the day", "sub": "stewards, metering, information", "x": 460, "y": 450, "w": 170, "h": 64, "sys": "policy", "detail": "One-way systems, holding areas, staggered times, metering at gates, clear communication, and stewards empowered to stop flows."}], "edges": [{"from": "dim", "to": "ramp", "label": "with"}, {"from": "dim", "to": "rate", "label": "design"}, {"from": "rate", "to": "width", "label": "÷"}, {"from": "time", "to": "width", "label": "÷"}, {"from": "ramp", "to": "ops", "label": "plans"}, {"from": "width", "to": "ops", "label": "limits", "sys": "policy"}], "tour": [{"focus": ["dim"], "text": "Start with DIM-ICE: what can go wrong in design, information and management, in each phase?"}, {"focus": ["ramp"], "text": "Then RAMP: which routes, which areas, how movement changes over time, and who the crowd is.", "edges": [["dim", "ramp"]]}, {"focus": ["rate", "time"], "text": "Choose planning flow rates and target times from the guidance that applies.", "edges": [["dim", "rate"]]}, {"focus": ["width"], "text": "Width needed = people ÷ (rate × time).", "edges": [["rate", "width"], ["time", "width"]]}, {"focus": ["ops"], "text": "On the day, management keeps density down: stewards, metering, information.", "edges": [["ramp", "ops"], ["width", "ops"]]}]}, "m2.1": {"title": "From video to the fundamental diagram", "caption": "Trajectories feed three measurements; together they give the fundamental diagram that every model must reproduce.", "nodes": [{"id": "vid", "label": "Video", "sub": "overhead cameras", "x": 120, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Overhead cameras record the scene. Software such as PeTrack (Jülich) detects heads and tracks them frame by frame."}, {"id": "traj", "label": "Trajectories", "sub": "x, y, t for each person", "x": 120, "y": 300, "w": 170, "h": 64, "sys": "water", "detail": "Positions of each person over time, usually at 16 to 25 frames per second, corrected for camera distortion."}, {"id": "rho", "label": "Density", "sub": "classical or Voronoi", "x": 440, "y": 100, "w": 170, "h": 64, "sys": "economy", "detail": "Classical: count in the area ÷ area. Voronoi: average of 1 ÷ cell area over the measurement area (Steffen and Seyfried 2010)."}, {"id": "vel", "label": "Speed", "sub": "Δposition ÷ Δt", "x": 440, "y": 260, "w": 170, "h": 64, "sys": "energy", "detail": "Each person's speed from positions a short time apart; the area speed averages over the people (or Voronoi cells) inside."}, {"id": "flw", "label": "Flow", "sub": "crossings per second", "x": 440, "y": 420, "w": 170, "h": 64, "sys": "energy", "detail": "Count people crossing a line per second; divide by width for specific flow."}, {"id": "fd", "label": "Fundamental diagram", "sub": "plot and compare", "x": 770, "y": 260, "w": 170, "h": 64, "sys": "neutral", "detail": "Plot speed or flow against density for many time windows. Check J ≈ ρ × v. Compare with other studies and models."}], "edges": [{"from": "vid", "to": "traj", "label": "track"}, {"from": "traj", "to": "rho", "label": ""}, {"from": "traj", "to": "vel", "label": ""}, {"from": "traj", "to": "flw", "label": ""}, {"from": "rho", "to": "fd", "label": ""}, {"from": "vel", "to": "fd", "label": ""}, {"from": "flw", "to": "fd", "label": "check"}], "tour": [{"focus": ["vid", "traj"], "text": "Cameras record the crowd; tracking software turns heads into trajectories.", "edges": [["vid", "traj"]]}, {"focus": ["rho"], "text": "Density: count heads in a box, or use Voronoi cells for a smoother measure.", "edges": [["traj", "rho"]]}, {"focus": ["vel", "flw"], "text": "Speed from movement over time; flow from people crossing a line.", "edges": [["traj", "vel"], ["traj", "flw"]]}, {"focus": ["fd"], "text": "Plot them together: the fundamental diagram. Check that flow ≈ density × speed.", "edges": [["rho", "fd"], ["vel", "fd"], ["flw", "fd"]]}]}, "m2.2": {"title": "Conservation plus a fundamental diagram", "caption": "People are conserved; the fundamental diagram gives the flow; demand and supply link the cells.", "nodes": [{"id": "cons", "label": "Conservation", "sub": "in − out = change", "x": 130, "y": 100, "w": 170, "h": 64, "sys": "neutral", "detail": "∂ρ/∂t + ∂(ρv)/∂x = 0: people do not appear or vanish."}, {"id": "fd", "label": "Fundamental diagram", "sub": "flow for each density", "x": 130, "y": 300, "w": 170, "h": 64, "sys": "energy", "detail": "J(ρ) closes the equation. Here Weidmann's curve."}, {"id": "dem", "label": "Demand", "sub": "what a cell can send", "x": 440, "y": 120, "w": 170, "h": 64, "sys": "energy", "detail": "Below critical density: J(ρ). Above: capacity. A congested cell can still send at capacity."}, {"id": "sup", "label": "Supply", "sub": "what a cell can receive", "x": 440, "y": 300, "w": 170, "h": 64, "sys": "land", "detail": "Below critical density: capacity. Above: J(ρ). A jammed cell can receive little. A narrower cell has proportionally less supply."}, {"id": "flux", "label": "Flow between cells", "sub": "min(demand, supply)", "x": 760, "y": 210, "w": 170, "h": 64, "sys": "energy", "detail": "The Godunov or cell-transmission rule: flow = min(upstream demand, downstream supply)."}, {"id": "jam", "label": "Jam and backward wave", "sub": "queue tail moves upstream", "x": 760, "y": 400, "w": 170, "h": 64, "sys": "climate", "detail": "At a bottleneck supply is low, so density builds and the queue's tail travels backwards at a speed set by the fundamental diagram."}, {"id": "hug", "label": "Hughes (2002)", "sub": "2-D, fastest route", "x": 440, "y": 460, "w": 170, "h": 64, "sys": "neutral", "detail": "Density moves down the gradient of a potential: the travel time to the goal at the local speed. A continuum crowd in 2-D."}], "edges": [{"from": "cons", "to": "flux", "label": ""}, {"from": "fd", "to": "dem", "label": ""}, {"from": "fd", "to": "sup", "label": ""}, {"from": "dem", "to": "flux", "label": "min"}, {"from": "sup", "to": "flux", "label": ""}, {"from": "flux", "to": "jam", "label": "at a bottleneck"}, {"from": "cons", "to": "hug", "label": "in 2-D", "sys": "neutral"}], "tour": [{"focus": ["cons"], "text": "Start from conservation: people in minus people out equals the change in a cell."}, {"focus": ["fd", "dem", "sup"], "text": "The fundamental diagram gives each cell a demand (what it can send) and a supply (what it can take).", "edges": [["fd", "dem"], ["fd", "sup"]]}, {"focus": ["flux"], "text": "The flow between two cells is the smaller of upstream demand and downstream supply.", "edges": [["dem", "flux"], ["sup", "flux"]]}, {"focus": ["jam"], "text": "At a bottleneck the supply is small, a jam forms, and its tail moves backwards.", "edges": [["flux", "jam"]]}, {"focus": ["hug"], "text": "Hughes took the same idea to 2-D, with people flowing down the fastest route.", "edges": [["cons", "hug"]]}]}, "m2.3": {"title": "How a floor-field cellular automaton moves people", "caption": "Each step, a person compares neighbouring cells using two floor fields and hops with a probability set by kS and kD.", "nodes": [{"id": "grid", "label": "Grid", "sub": "0.4 m cells, one person each", "x": 130, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "The floor becomes a lattice. 0.4 m × 0.4 m is about the space of one person in a dense crowd (6.25 per m² at full occupancy)."}, {"id": "sf", "label": "Static field S", "sub": "distance to the exit", "x": 130, "y": 300, "w": 170, "h": 64, "sys": "land", "detail": "Fixed in time. Lower S = closer to the exit. Weighted by kS."}, {"id": "df", "label": "Dynamic field D", "sub": "fading trails", "x": 130, "y": 460, "w": 170, "h": 64, "sys": "economy", "detail": "Each move leaves a trace that decays and diffuses. Following trails creates lanes and herding. Weighted by kD."}, {"id": "prob", "label": "Choice probability", "sub": "∝ exp(−kS·S + kD·D)", "x": 470, "y": 300, "w": 170, "h": 64, "sys": "neutral", "detail": "For each free neighbour cell (and staying put), weight = exp(−kS·S + kD·D); choose at random in proportion."}, {"id": "upd", "label": "Update order", "sub": "random sequential or parallel", "x": 470, "y": 110, "w": 170, "h": 64, "sys": "neutral", "detail": "Random sequential: people move one at a time in random order. Parallel update needs rules for conflicts when two want the same cell."}, {"id": "time", "label": "Time step", "sub": "≈ 0.3 s", "x": 780, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "One cell per step at 0.4 m: free speed ≈ 0.4 ÷ 0.3 ≈ 1.3 m/s."}, {"id": "cal", "label": "Calibration", "sub": "exit flow, speed", "x": 780, "y": 400, "w": 170, "h": 64, "sys": "water", "detail": "The plain model lets one person leave per exit cell per step, about 8 per m per s: too high. Friction or an exit probability brings it to 1.3–1.9."}], "edges": [{"from": "grid", "to": "sf", "label": ""}, {"from": "sf", "to": "prob", "label": "kS"}, {"from": "df", "to": "prob", "label": "kD"}, {"from": "upd", "to": "prob", "label": ""}, {"from": "prob", "to": "time", "label": "per step"}, {"from": "time", "to": "cal", "label": ""}, {"from": "prob", "to": "cal", "label": "check"}], "tour": [{"focus": ["grid"], "text": "The floor is a grid of 40 cm cells; each holds at most one person."}, {"focus": ["sf", "df"], "text": "Two floor fields guide people: distance to the exit, and fading trails left by others."}, {"focus": ["prob"], "text": "Each person scores neighbouring cells by exp(−kS·S + kD·D) and picks one at random in proportion.", "edges": [["sf", "prob"], ["df", "prob"]]}, {"focus": ["upd", "time"], "text": "Everyone moves once per step, about 0.3 s, in random order.", "edges": [["upd", "prob"], ["prob", "time"]]}, {"focus": ["cal"], "text": "Then calibrate: the plain model's exit flow is far too high.", "edges": [["time", "cal"], ["prob", "cal"]]}]}, "m2.4": {"title": "Forces on one person", "caption": "Driving force towards the goal, repulsion from others and walls, and contact forces when bodies touch.", "nodes": [{"id": "goal", "label": "Goal", "sub": "door or target", "x": 770, "y": 120, "w": 170, "h": 64, "sys": "land", "detail": "The direction e towards the next target, for example the nearest point of the door."}, {"id": "drv", "label": "Driving force", "sub": "m(v₀e − v)/τ", "x": 450, "y": 120, "w": 170, "h": 64, "sys": "economy", "detail": "Relaxes the velocity towards the desired velocity v₀e over the relaxation time τ (about 0.5 s)."}, {"id": "soc", "label": "Social repulsion", "sub": "A·exp((r−d)/B)", "x": 130, "y": 220, "w": 170, "h": 64, "sys": "economy", "detail": "Grows exponentially as people approach: A sets strength, B the range (Helbing, Farkas and Vicsek 2000 used A = 2,000 N, B = 0.08 m)."}, {"id": "body", "label": "Contact forces", "sub": "body force and friction", "x": 130, "y": 400, "w": 170, "h": 64, "sys": "climate", "detail": "When bodies overlap: body force k·g (k = 1.2×10⁵ kg/s²) and sliding friction κ·g·Δv (κ = 2.4×10⁵ kg/(m·s))."}, {"id": "wall", "label": "Walls", "sub": "same forms", "x": 450, "y": 450, "w": 170, "h": 64, "sys": "land", "detail": "Repulsion and contact forces from walls and obstacles."}, {"id": "acc", "label": "Acceleration", "sub": "m dv/dt = ΣF", "x": 450, "y": 290, "w": 170, "h": 64, "sys": "neutral", "detail": "Sum the forces, divide by mass, integrate with a small time step to update velocity and position."}, {"id": "emg", "label": "Emergent effects", "sub": "lanes, clogging, faster-is-slower", "x": 770, "y": 380, "w": 170, "h": 64, "sys": "energy", "detail": "Lanes in counterflow, oscillations at doors, arches and clogging at exits, faster-is-slower."}], "edges": [{"from": "goal", "to": "drv", "label": "direction"}, {"from": "drv", "to": "acc", "label": ""}, {"from": "soc", "to": "acc", "label": ""}, {"from": "body", "to": "acc", "label": ""}, {"from": "wall", "to": "acc", "label": ""}, {"from": "acc", "to": "emg", "label": "many people"}], "tour": [{"focus": ["goal", "drv"], "text": "A driving force pulls each person towards the goal at their desired speed.", "edges": [["goal", "drv"]]}, {"focus": ["soc"], "text": "Other people push back, more strongly the closer they are.", "edges": [["soc", "acc"]]}, {"focus": ["body", "wall"], "text": "When bodies touch, contact forces and friction act; walls push too.", "edges": [["body", "acc"], ["wall", "acc"]]}, {"focus": ["acc"], "text": "Add the forces up and Newton's law moves everyone a small step.", "edges": [["drv", "acc"]]}, {"focus": ["emg"], "text": "With many people, lanes, clogging and faster-is-slower emerge.", "edges": [["acc", "emg"]]}]}, "m2.5": {"title": "From hand calculation to cognition", "caption": "Model families ordered by detail. More detail means more realism in some respects, more parameters and more computing.", "nodes": [{"id": "hyd", "label": "Hydraulic", "sub": "flow rates by hand", "x": 110, "y": 110, "w": 170, "h": 64, "sys": "policy", "detail": "Egress time from flow rates and walking speeds (SFPE Handbook, PD 7974-6, Green Guide). Transparent, fast, no behaviour."}, {"id": "mac", "label": "Macroscopic", "sub": "density fields", "x": 330, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Continuum or cell-transmission models (module 2.2). Large networks, real-time forecasts."}, {"id": "ca", "label": "Cellular automata", "sub": "grid hops", "x": 550, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "Floor-field CAs (module 2.3). Fast, discrete, need calibration."}, {"id": "sfm", "label": "Force-based", "sub": "social force", "x": 770, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Social force and variants (module 2.4). Contact, clogging, pushing."}, {"id": "vel", "label": "Velocity-based", "sub": "choose a safe speed", "x": 220, "y": 320, "w": 170, "h": 64, "sys": "energy", "detail": "Speed and direction chosen directly to avoid collisions, e.g. the collision-free speed model (Tordeux, Chraibi and Seyfried 2016) or ORCA."}, {"id": "osm", "label": "Optimal steps", "sub": "best step on a circle", "x": 450, "y": 320, "w": 170, "h": 64, "sys": "economy", "detail": "Discrete steps to the best point on a circle (Seitz and Köster 2012), implemented in Vadere."}, {"id": "heu", "label": "Cognitive heuristics", "sub": "look, then go", "x": 680, "y": 320, "w": 170, "h": 64, "sys": "economy", "detail": "Visual heuristics: head for the direction with the longest free walk towards the goal; keep a time gap (Moussaïd, Helbing and Theraulaz 2011)."}, {"id": "q", "label": "Your question", "sub": "decides the choice", "x": 450, "y": 460, "w": 170, "h": 64, "sys": "policy", "detail": "Scale, phenomenon, data available, time and the need to explain results to decision makers."}], "edges": [{"from": "hyd", "to": "mac", "label": "more detail"}, {"from": "mac", "to": "ca", "label": ""}, {"from": "ca", "to": "sfm", "label": ""}, {"from": "q", "to": "vel", "label": ""}, {"from": "q", "to": "osm", "label": ""}, {"from": "q", "to": "heu", "label": ""}, {"from": "q", "to": "hyd", "label": "or simple", "sys": "policy"}], "tour": [{"focus": ["hyd"], "text": "At one end, a hand calculation with flow rates: transparent and quick."}, {"focus": ["mac", "ca", "sfm"], "text": "Then macroscopic fields, grid hops and forces: more detail, more parameters.", "edges": [["hyd", "mac"], ["mac", "ca"], ["ca", "sfm"]]}, {"focus": ["vel", "osm"], "text": "Velocity and step models choose speeds or steps directly to avoid collisions."}, {"focus": ["heu"], "text": "Cognitive heuristics model what people see and decide."}, {"focus": ["q"], "text": "Your question decides which family to use.", "edges": [["q", "vel"], ["q", "osm"], ["q", "heu"], ["q", "hyd"]]}]}, "m2.6": {"title": "From geometry to choices", "caption": "Distance fields give the shortest path; adding expected waiting gives the quickest path; guidance nudges the crowd towards the best split.", "nodes": [{"id": "geo", "label": "Geometry", "sub": "walls, exits, routes", "x": 120, "y": 110, "w": 170, "h": 64, "sys": "land", "detail": "The layout and the possible routes."}, {"id": "dist", "label": "Distance field", "sub": "shortest path", "x": 120, "y": 300, "w": 170, "h": 64, "sys": "neutral", "detail": "Distance to each exit, computed with the fast marching method or a graph. Leads everyone to the nearest exit."}, {"id": "time", "label": "Expected time", "sub": "walk + wait", "x": 440, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Walking time plus expected queuing time, updated as queues grow (quickest path)."}, {"id": "ue", "label": "User equilibrium", "sub": "nobody gains by switching", "x": 440, "y": 300, "w": 170, "h": 64, "sys": "economy", "detail": "Each person picks their quickest route; at equilibrium all used routes take equal time."}, {"id": "so", "label": "System optimum", "sub": "best for all", "x": 760, "y": 300, "w": 170, "h": 64, "sys": "policy", "detail": "The split that minimises total evacuation time or total delay; may differ from the user equilibrium."}, {"id": "info", "label": "Guidance", "sub": "signs, stewards, apps", "x": 760, "y": 110, "w": 170, "h": 64, "sys": "policy", "detail": "Dynamic signs, stewards and apps can push choices towards the system optimum."}, {"id": "hab", "label": "Habit and herding", "sub": "real behaviour", "x": 440, "y": 460, "w": 170, "h": 64, "sys": "economy", "detail": "Familiarity, following others and group decisions bias real choices (module 1.6)."}], "edges": [{"from": "geo", "to": "dist", "label": ""}, {"from": "dist", "to": "time", "label": "+ queues"}, {"from": "time", "to": "ue", "label": "selfish"}, {"from": "ue", "to": "so", "label": "gap?"}, {"from": "info", "to": "so", "label": "nudges", "sys": "policy"}, {"from": "hab", "to": "ue", "label": "biases"}], "tour": [{"focus": ["geo", "dist"], "text": "Start from the layout: a distance field gives each person their shortest path.", "edges": [["geo", "dist"]]}, {"focus": ["time"], "text": "Add expected waiting time and you get the quickest path.", "edges": [["dist", "time"]]}, {"focus": ["ue"], "text": "If everyone chooses their own quickest path, the crowd reaches a user equilibrium.", "edges": [["time", "ue"]]}, {"focus": ["so"], "text": "The best split for everyone, the system optimum, can be different.", "edges": [["ue", "so"]]}, {"focus": ["info", "hab"], "text": "Guidance nudges people towards it; habit and herding pull the other way.", "edges": [["info", "so"], ["hab", "ue"]]}]}, "m2.7": {"title": "RSET against ASET", "caption": "Four parts add up to the time people need; it must stay below the time conditions allow, with a margin.", "nodes": [{"id": "det", "label": "Detection", "sub": "alarm triggered", "x": 120, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Time from ignition (or an incident) to detection, from detector design or fire modelling."}, {"id": "warn", "label": "Warning", "sub": "people alerted", "x": 340, "y": 110, "w": 170, "h": 64, "sys": "policy", "detail": "Time to alert people: alarms, voice messages, staff. Voice messages work better than bells."}, {"id": "pre", "label": "Pre-movement", "sub": "notice, decide, gather", "x": 560, "y": 110, "w": 170, "h": 64, "sys": "economy", "detail": "Recognition and response. Often the longest and most variable part; depends on alertness, familiarity, staff and message quality."}, {"id": "mov", "label": "Movement", "sub": "walk and queue", "x": 780, "y": 110, "w": 170, "h": 64, "sys": "energy", "detail": "Hydraulic estimate: max(walking time, people ÷ exit capacity), or a simulation."}, {"id": "rset", "label": "RSET", "sub": "sum of the four", "x": 450, "y": 300, "w": 170, "h": 64, "sys": "climate", "detail": "Required safe egress time = detection + warning + pre-movement + movement."}, {"id": "aset", "label": "ASET", "sub": "from fire and smoke", "x": 780, "y": 300, "w": 170, "h": 64, "sys": "climate", "detail": "Available safe egress time: until smoke, heat or toxicity become untenable, from fire modelling."}, {"id": "dist", "label": "As a distribution", "sub": "percentiles, margin", "x": 450, "y": 450, "w": 170, "h": 64, "sys": "water", "detail": "Sample uncertain inputs (Monte Carlo) and compare high percentiles of RSET with ASET."}], "edges": [{"from": "det", "to": "rset", "label": ""}, {"from": "warn", "to": "rset", "label": ""}, {"from": "pre", "to": "rset", "label": "largest"}, {"from": "mov", "to": "rset", "label": ""}, {"from": "rset", "to": "aset", "label": "must be <"}, {"from": "rset", "to": "dist", "label": "uncertain"}], "tour": [{"focus": ["det", "warn"], "text": "First the fire must be detected and people warned.", "edges": [["det", "rset"], ["warn", "rset"]]}, {"focus": ["pre"], "text": "Then people notice, decide and gather: pre-movement, often the longest part.", "edges": [["pre", "rset"]]}, {"focus": ["mov"], "text": "Then they walk and queue through the exits.", "edges": [["mov", "rset"]]}, {"focus": ["rset", "aset"], "text": "The four add up to RSET, which must stay below ASET with a margin.", "edges": [["rset", "aset"]]}, {"focus": ["dist"], "text": "Because the inputs are uncertain, treat RSET as a distribution.", "edges": [["rset", "dist"]]}]}, "m2.8": {"title": "From code to a trustworthy model", "caption": "Verify the code, calibrate on one data set, validate on another, then quantify uncertainty.", "nodes": [{"id": "ver", "label": "Verification", "sub": "does the code match the equations?", "x": 130, "y": 110, "w": 170, "h": 64, "sys": "neutral", "detail": "Unit tests and simple analytic cases: a single person walks at v₀, nobody passes through walls."}, {"id": "data", "label": "Data", "sub": "FD, bottleneck flow, travel times", "x": 130, "y": 300, "w": 170, "h": 64, "sys": "water", "detail": "Experiments (Jülich archive), field counts, video. Split into calibration and validation sets."}, {"id": "cal", "label": "Calibration", "sub": "fit parameters", "x": 450, "y": 210, "w": 170, "h": 64, "sys": "water", "detail": "Choose parameters that minimise an error such as RMSE across several observables."}, {"id": "val", "label": "Validation", "sub": "test on unseen data", "x": 760, "y": 210, "w": 170, "h": 64, "sys": "water", "detail": "Run the calibrated model on new scenarios or held-out data and compare."}, {"id": "std", "label": "Standard tests", "sub": "RiMEA, NIST", "x": 450, "y": 420, "w": 170, "h": 64, "sys": "policy", "detail": "Benchmark scenarios that any evacuation simulator should pass."}, {"id": "unc", "label": "Uncertainty", "sub": "ranges, ensembles", "x": 760, "y": 420, "w": 170, "h": 64, "sys": "climate", "detail": "Parameter ranges, several models, stochastic repeats; report spread and percentiles."}], "edges": [{"from": "ver", "to": "cal", "label": "first"}, {"from": "data", "to": "cal", "label": "calibration set"}, {"from": "cal", "to": "val", "label": ""}, {"from": "data", "to": "val", "label": "validation set"}, {"from": "std", "to": "val", "label": "also"}, {"from": "val", "to": "unc", "label": "then"}], "tour": [{"focus": ["ver"], "text": "First verify: the code does what the equations say."}, {"focus": ["data", "cal"], "text": "Then calibrate parameters on part of the data, using several observables.", "edges": [["data", "cal"], ["ver", "cal"]]}, {"focus": ["val"], "text": "Validate on data the model has not seen.", "edges": [["cal", "val"], ["data", "val"]]}, {"focus": ["std"], "text": "Pass standard test cases too.", "edges": [["std", "val"]]}, {"focus": ["unc"], "text": "Finally, quantify and report uncertainty.", "edges": [["val", "unc"]]}]}, "m3.1": {"title": "The anatomy of a mass-gathering study", "caption": "Question, outcomes, scenarios, data and ethics fit together; each constrains the others.", "nodes": [{"id": "q", "label": "Research question", "sub": "specific, answerable", "x": 450, "y": 80, "w": 170, "h": 64, "sys": "policy", "detail": "Population, intervention, comparison, outcome: for example, staggered departures vs current schedule, outcome = person-minutes above 4 per m² on route X."}, {"id": "out", "label": "Outcome measures", "sub": "exposure, times, flows", "x": 130, "y": 230, "w": 170, "h": 64, "sys": "climate", "detail": "Peak density, time above thresholds, risk exposure (person-minutes above a threshold), waiting times, throughput."}, {"id": "scn", "label": "Scenario design", "sub": "factors × levels", "x": 450, "y": 230, "w": 170, "h": 64, "sys": "neutral", "detail": "Demand, schedules, layout, management; full or fractional factorial designs to capture interactions."}, {"id": "mdl", "label": "Model choice", "sub": "fit for the question", "x": 770, "y": 230, "w": 170, "h": 64, "sys": "neutral", "detail": "From module 2.5: macro for networks, micro for hot spots, often both."}, {"id": "dat", "label": "Data plan", "sub": "counts, video, schedules", "x": 130, "y": 420, "w": 170, "h": 64, "sys": "water", "detail": "Site plans, schedules, gate counts, CCTV, phone data; which data calibrate and which validate."}, {"id": "eth", "label": "Ethics and access", "sub": "privacy, consent, partners", "x": 450, "y": 420, "w": 170, "h": 64, "sys": "economy", "detail": "Video privacy, data protection, approvals, and partnership with the authorities and communities."}, {"id": "rep", "label": "Reporting", "sub": "honest about limits", "x": 770, "y": 420, "w": 170, "h": 64, "sys": "policy", "detail": "Uncertainty, model limits, and what decision makers can and cannot conclude."}], "edges": [{"from": "q", "to": "out", "label": "defines"}, {"from": "q", "to": "scn", "label": ""}, {"from": "scn", "to": "mdl", "label": ""}, {"from": "dat", "to": "mdl", "label": "calibrate"}, {"from": "eth", "to": "dat", "label": "constrains"}, {"from": "mdl", "to": "rep", "label": ""}, {"from": "out", "to": "rep", "label": ""}], "tour": [{"focus": ["q"], "text": "Start with a specific, answerable question."}, {"focus": ["out"], "text": "Decide how you will measure success: exposure, not just peaks.", "edges": [["q", "out"]]}, {"focus": ["scn", "mdl"], "text": "Design scenarios and pick a model fit for the question.", "edges": [["q", "scn"], ["scn", "mdl"]]}, {"focus": ["dat", "eth"], "text": "Plan your data and the ethics and partnerships that make it possible.", "edges": [["dat", "mdl"], ["eth", "dat"]]}, {"focus": ["rep"], "text": "Plan how you will report, including limits.", "edges": [["mdl", "rep"], ["out", "rep"]]}]}, "m3.2": {"title": "From underlying causes to a crush", "caption": "Underlying failures in design, information and management create the conditions; a trigger and high density produce the proximate cause.", "nodes": [{"id": "des", "label": "Design", "sub": "routes, widths, slopes", "x": 130, "y": 100, "w": 170, "h": 64, "sys": "land", "detail": "Single routes for both directions, narrowings, slopes, dead ends, inadequate holding space."}, {"id": "inf", "label": "Information", "sub": "what people know", "x": 130, "y": 260, "w": 170, "h": 64, "sys": "economy", "detail": "People at the back cannot see the front; no warnings; unclear signs; control rooms without good views or counts."}, {"id": "man", "label": "Management", "sub": "decisions, staff, plans", "x": 130, "y": 420, "w": 170, "h": 64, "sys": "policy", "detail": "Opening gates into full areas, no event plan, unclear responsibilities, late responses to warnings."}, {"id": "cond", "label": "Dangerous conditions", "sub": "flows meet, density rises", "x": 470, "y": 260, "w": 170, "h": 64, "sys": "climate", "detail": "Converging or opposing flows in a confined space faster than it empties."}, {"id": "trig", "label": "Trigger", "sub": "gate opened, fall, surge", "x": 470, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "Often small: a gate opened, a person falling, a surge towards an attraction."}, {"id": "prox", "label": "Proximate cause", "sub": "crush, collapse", "x": 790, "y": 260, "w": 170, "h": 64, "sys": "climate", "detail": "Compressive asphyxia in a crowd collapse or crush."}, {"id": "sys", "label": "Systemic failure", "sub": "many small failures align", "x": 790, "y": 100, "w": 170, "h": 64, "sys": "policy", "detail": "No single cause: many weaknesses line up (Helbing and Mukerji 2012)."}], "edges": [{"from": "des", "to": "cond", "label": ""}, {"from": "inf", "to": "cond", "label": ""}, {"from": "man", "to": "cond", "label": ""}, {"from": "cond", "to": "prox", "label": "density"}, {"from": "trig", "to": "prox", "label": "tips"}, {"from": "prox", "to": "sys", "label": "seen as"}], "tour": [{"focus": ["des", "inf", "man"], "text": "Underlying causes lie in design, information and management."}, {"focus": ["cond"], "text": "Together they create dangerous conditions: flows meeting in confined spaces.", "edges": [["des", "cond"], ["inf", "cond"], ["man", "cond"]]}, {"focus": ["trig"], "text": "A small trigger can tip the situation.", "edges": [["trig", "prox"]]}, {"focus": ["prox"], "text": "The proximate cause is the crush itself.", "edges": [["cond", "prox"]]}, {"focus": ["sys"], "text": "Seen as a whole, it is a systemic failure: many small weaknesses aligned.", "edges": [["prox", "sys"]]}]}, "m3.3": {"title": "The Hajj as a crowd system", "caption": "A fixed ritual sequence synchronises demand; infrastructure, routing and scheduling spread and separate it.", "nodes": [{"id": "rit", "label": "Ritual sequence", "sub": "fixed days and places", "x": 130, "y": 100, "w": 170, "h": 64, "sys": "economy", "detail": "Makkah, Mina, Arafat, Muzdalifah, Jamarat, in an order and on days set by the rites. Demand is synchronised."}, {"id": "grp", "label": "Pilgrim groups", "sub": "by country and company", "x": 130, "y": 270, "w": 170, "h": 64, "sys": "economy", "detail": "Pilgrims travel in organised groups with leaders, which makes scheduling possible."}, {"id": "inf", "label": "Infrastructure", "sub": "multi-level Jamarat, metro", "x": 460, "y": 100, "w": 170, "h": 64, "sys": "land", "detail": "After 2006 the Jamarat Bridge was rebuilt with several levels, wide ramps and one-way flows; a metro line links the holy sites."}, {"id": "rt", "label": "Routing", "sub": "one-way, separated streams", "x": 460, "y": 270, "w": 170, "h": 64, "sys": "land", "detail": "Separate routes to and from the Jamarat, one-way systems, and avoidance of crossing and opposing flows."}, {"id": "sch", "label": "Scheduling", "sub": "time slots per group", "x": 460, "y": 440, "w": 170, "h": 64, "sys": "policy", "detail": "Groups are assigned time slots for movements such as the stoning ritual, spreading demand over the day."}, {"id": "mon", "label": "Monitoring", "sub": "CCTV, control rooms", "x": 780, "y": 270, "w": 170, "h": 64, "sys": "water", "detail": "Control rooms watch density and flows and can adjust routes and release times."}, {"id": "risk", "label": "Residual risks", "sub": "non-compliance, heat", "x": 780, "y": 440, "w": 170, "h": 64, "sys": "climate", "detail": "Groups leaving outside their slot, unregistered pilgrims, heat and health emergencies."}], "edges": [{"from": "rit", "to": "grp", "label": ""}, {"from": "grp", "to": "sch", "label": "assigned"}, {"from": "inf", "to": "rt", "label": "enables"}, {"from": "sch", "to": "rt", "label": "spreads load"}, {"from": "rt", "to": "mon", "label": ""}, {"from": "mon", "to": "sch", "label": "adjusts", "sys": "policy"}, {"from": "risk", "to": "sch", "label": "undermines"}], "tour": [{"focus": ["rit", "grp"], "text": "A fixed ritual sequence means everyone needs the same places at the same times; pilgrims move in organised groups.", "edges": [["rit", "grp"]]}, {"focus": ["inf", "rt"], "text": "Infrastructure and routing separate the streams: the multi-level Jamarat and one-way routes.", "edges": [["inf", "rt"]]}, {"focus": ["sch"], "text": "Scheduling assigns groups to time slots to spread demand.", "edges": [["grp", "sch"], ["sch", "rt"]]}, {"focus": ["mon"], "text": "Control rooms monitor and adjust.", "edges": [["rt", "mon"], ["mon", "sch"]]}, {"focus": ["risk"], "text": "Residual risks: groups ignoring slots, unregistered pilgrims, heat.", "edges": [["risk", "sch"]]}]}, "m3.4": {"title": "Four ways to count a crowd", "caption": "Area × density, computer vision, overhead imagery and phone data each give an estimate with its own errors; combine and calibrate them.", "nodes": [{"id": "jac", "label": "Jacobs' method", "sub": "area × density per zone", "x": 130, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Divide into zones, multiply area by assumed density, add. Simple; sensitive to the densities assumed."}, {"id": "cv", "label": "Computer vision", "sub": "density maps from CCTV", "x": 130, "y": 290, "w": 170, "h": 64, "sys": "water", "detail": "Convolutional networks predict a density map; the count is its sum (Zhang et al. 2016, ShanghaiTech)."}, {"id": "uav", "label": "Drones and overhead", "sub": "near-orthographic views", "x": 130, "y": 450, "w": 170, "h": 64, "sys": "water", "detail": "Overhead images reduce perspective and occlusion; need permits and safety rules."}, {"id": "ph", "label": "Phone data", "sub": "network, Wi-Fi, Bluetooth", "x": 450, "y": 450, "w": 170, "h": 64, "sys": "water", "detail": "Coverage of large areas over time; biased by phone ownership and settings; privacy-sensitive."}, {"id": "fuse", "label": "Combine and calibrate", "sub": "ground truth, intervals", "x": 450, "y": 210, "w": 170, "h": 64, "sys": "neutral", "detail": "Calibrate each source against manual counts, combine them, and report intervals."}, {"id": "use", "label": "Use", "sub": "density, flows, alerts", "x": 780, "y": 210, "w": 170, "h": 64, "sys": "policy", "detail": "Feed density and flow estimates to control rooms and models (module 3.5)."}, {"id": "priv", "label": "Privacy", "sub": "minimise, anonymise", "x": 780, "y": 420, "w": 170, "h": 64, "sys": "economy", "detail": "Count without identifying; aggregate; store securely; follow the law and ethics approvals."}], "edges": [{"from": "jac", "to": "fuse", "label": ""}, {"from": "cv", "to": "fuse", "label": ""}, {"from": "uav", "to": "fuse", "label": ""}, {"from": "ph", "to": "fuse", "label": ""}, {"from": "fuse", "to": "use", "label": ""}, {"from": "priv", "to": "use", "label": "governs", "sys": "economy"}, {"from": "priv", "to": "ph", "label": "constrains", "sys": "economy"}], "tour": [{"focus": ["jac"], "text": "The oldest method: zone areas times densities."}, {"focus": ["cv", "uav"], "text": "Computer vision turns CCTV and drone images into density maps."}, {"focus": ["ph"], "text": "Phone data cover large areas over time, with biases."}, {"focus": ["fuse"], "text": "Calibrate each source and combine them, reporting intervals.", "edges": [["jac", "fuse"], ["cv", "fuse"], ["uav", "fuse"], ["ph", "fuse"]]}, {"focus": ["use", "priv"], "text": "Use the estimates for monitoring, under strict privacy rules.", "edges": [["fuse", "use"], ["priv", "use"]]}]}, "m3.5": {"title": "From cameras to decisions", "caption": "Measurements feed indicators; indicators cross levels; each level triggers a defined action by someone with authority.", "nodes": [{"id": "cam", "label": "Cameras and sensors", "sub": "CCTV, counters, phones", "x": 120, "y": 110, "w": 170, "h": 64, "sys": "water", "detail": "Fixed cameras, gate counters, phone data. Coverage of critical points (bottlenecks, junctions, ramps) matters most."}, {"id": "est", "label": "Estimation", "sub": "density and velocity maps", "x": 120, "y": 300, "w": 170, "h": 64, "sys": "water", "detail": "Density from counting networks; velocity from optical flow or tracking, per cell and per second."}, {"id": "ind", "label": "Indicators", "sub": "density, flow, pressure", "x": 440, "y": 200, "w": 170, "h": 64, "sys": "climate", "detail": "Local density, flow against capacity, crowd pressure ρ·Var(V), queue growth, counterflow."}, {"id": "lev", "label": "Levels", "sub": "watch, act", "x": 440, "y": 400, "w": 170, "h": 64, "sys": "policy", "detail": "Thresholds set in advance from data and guidance; tested in exercises; adjusted for the site."}, {"id": "act", "label": "Actions", "sub": "stop inflow, relieve, inform", "x": 760, "y": 400, "w": 170, "h": 64, "sys": "policy", "detail": "Predefined responses: hold or meter inflow, open relief routes, announcements, deploy stewards."}, {"id": "fc", "label": "Forecasts", "sub": "minutes ahead", "x": 760, "y": 200, "w": 170, "h": 64, "sys": "neutral", "detail": "Models fed by live counts forecast density 10–30 minutes ahead, extending lead time; a 'digital twin' keeps model and site in step."}, {"id": "auth", "label": "Authority", "sub": "who decides", "x": 760, "y": 60, "w": 170, "h": 64, "sys": "economy", "detail": "Clear roles: who can stop inflow or close a gate, without waiting for approval up a long chain."}], "edges": [{"from": "cam", "to": "est", "label": ""}, {"from": "est", "to": "ind", "label": ""}, {"from": "ind", "to": "lev", "label": "crosses"}, {"from": "lev", "to": "act", "label": "triggers"}, {"from": "ind", "to": "fc", "label": "feeds"}, {"from": "fc", "to": "lev", "label": "earlier"}, {"from": "auth", "to": "act", "label": "empowers", "sys": "economy"}], "tour": [{"focus": ["cam", "est"], "text": "Cameras and sensors give data; estimation turns it into density and velocity maps.", "edges": [["cam", "est"]]}, {"focus": ["ind"], "text": "Indicators summarise risk: density, flow, crowd pressure.", "edges": [["est", "ind"]]}, {"focus": ["lev", "act"], "text": "When an indicator crosses a level, a predefined action starts.", "edges": [["ind", "lev"], ["lev", "act"]]}, {"focus": ["fc"], "text": "Forecasts give warnings earlier, extending lead time.", "edges": [["ind", "fc"], ["fc", "lev"]]}, {"focus": ["auth"], "text": "Someone must have the authority to act at once.", "edges": [["auth", "act"]]}]}, "m3.6": {"title": "A simulation study, step by step", "caption": "Each step feeds the next; uncertainty enters at every step and must be carried through to the results.", "nodes": [{"id": "geo", "label": "Geometry", "sub": "plans, checked on site", "x": 110, "y": 100, "w": 170, "h": 64, "sys": "land", "detail": "Walkable areas, obstacles, gates, ramps. Temporary structures (stalls, barriers, tents) matter."}, {"id": "dem", "label": "Demand", "sub": "numbers, timing, destinations", "x": 330, "y": 100, "w": 170, "h": 64, "sys": "economy", "detail": "From schedules, tickets, counts. Include profiles: speeds, groups, mobility."}, {"id": "mod", "label": "Model", "sub": "macro + micro", "x": 550, "y": 100, "w": 170, "h": 64, "sys": "neutral", "detail": "Network or macro model for the whole site; micro model for hot spots; calibrated."}, {"id": "run", "label": "Runs", "sub": "scenarios × seeds", "x": 770, "y": 100, "w": 170, "h": 64, "sys": "neutral", "detail": "Repeat stochastic runs; record outputs consistently."}, {"id": "sen", "label": "Sensitivity", "sub": "vary uncertain inputs", "x": 770, "y": 300, "w": 170, "h": 64, "sys": "water", "detail": "One-at-a-time screening, then Monte Carlo or variance-based methods for key inputs."}, {"id": "out", "label": "Outputs", "sub": "exposure, times, flows", "x": 450, "y": 300, "w": 170, "h": 64, "sys": "climate", "detail": "Answer the research question: risk exposure, time above thresholds, clearance times, with spread."}, {"id": "rep", "label": "Reproducibility", "sub": "code, data, versions", "x": 130, "y": 300, "w": 170, "h": 64, "sys": "policy", "detail": "Share scripts, geometry and parameter files, simulator versions and seeds."}], "edges": [{"from": "geo", "to": "dem", "label": ""}, {"from": "dem", "to": "mod", "label": ""}, {"from": "mod", "to": "run", "label": ""}, {"from": "run", "to": "sen", "label": ""}, {"from": "sen", "to": "out", "label": ""}, {"from": "run", "to": "out", "label": ""}, {"from": "out", "to": "rep", "label": "documented"}], "tour": [{"focus": ["geo", "dem"], "text": "Start with geometry and demand, checked against the real site.", "edges": [["geo", "dem"]]}, {"focus": ["mod"], "text": "Choose and calibrate a model, often macro for the network and micro for hot spots.", "edges": [["dem", "mod"]]}, {"focus": ["run"], "text": "Run every scenario with several random seeds.", "edges": [["mod", "run"]]}, {"focus": ["sen", "out"], "text": "Vary uncertain inputs, then report outputs with their spread.", "edges": [["run", "sen"], ["sen", "out"]]}, {"focus": ["rep"], "text": "Document everything so others can reproduce it.", "edges": [["out", "rep"]]}]}, "m3.7": {"title": "Interventions move risk as well as reduce it", "caption": "Each tool lowers density somewhere; evaluation checks where the waiting went and whether that place is safe.", "nodes": [{"id": "met", "label": "Metering", "sub": "limit inflow rate", "x": 130, "y": 100, "w": 170, "h": 64, "sys": "policy", "detail": "Gates or stewards admit people at a set rate; waiting moves upstream."}, {"id": "one", "label": "One-way systems", "sub": "separate opposing flows", "x": 130, "y": 260, "w": 170, "h": 64, "sys": "land", "detail": "Separate routes in and out; no head-on conflicts in narrow spaces."}, {"id": "hold", "label": "Holding areas", "sub": "store and release", "x": 130, "y": 420, "w": 170, "h": 64, "sys": "land", "detail": "Pens or zones where people wait safely and are released in batches."}, {"id": "sch", "label": "Scheduling and information", "sub": "spread demand", "x": 450, "y": 420, "w": 170, "h": 64, "sys": "economy", "detail": "Time slots, staggered starts, real-time information and stewards."}, {"id": "den", "label": "Density at the hot spot", "sub": "goes down", "x": 450, "y": 180, "w": 170, "h": 64, "sys": "climate", "detail": "The intended effect."}, {"id": "side", "label": "Side effects", "sub": "queues elsewhere, longer routes", "x": 770, "y": 100, "w": 170, "h": 64, "sys": "climate", "detail": "Waiting moves upstream; routes lengthen; holding areas can become hot spots themselves."}, {"id": "eval", "label": "Evaluation", "sub": "baseline, simulation, data", "x": 770, "y": 320, "w": 170, "h": 64, "sys": "water", "detail": "Fair comparison, sensitivity analysis, monitoring after implementation."}], "edges": [{"from": "met", "to": "den", "label": ""}, {"from": "one", "to": "den", "label": ""}, {"from": "hold", "to": "den", "label": ""}, {"from": "sch", "to": "den", "label": ""}, {"from": "met", "to": "side", "label": "moves queue"}, {"from": "hold", "to": "side", "label": "if not released"}, {"from": "den", "to": "eval", "label": ""}, {"from": "side", "to": "eval", "label": ""}], "tour": [{"focus": ["met", "one", "hold", "sch"], "text": "Four families of tools: metering, one-way systems, holding areas, scheduling and information."}, {"focus": ["den"], "text": "All aim to keep density down at the hot spot.", "edges": [["met", "den"], ["one", "den"], ["hold", "den"], ["sch", "den"]]}, {"focus": ["side"], "text": "But they move risk: queues upstream, longer routes, new hot spots.", "edges": [["met", "side"], ["hold", "side"]]}, {"focus": ["eval"], "text": "So evaluate both the intended effect and the side effects.", "edges": [["den", "eval"], ["side", "eval"]]}]}, "m3.8": {"title": "Open questions around a crowd study", "caption": "Five research fronts, and the reporting that turns a study into something decision makers can use.", "nodes": [{"id": "push", "label": "Pushing and forces", "sub": "what is truly critical?", "x": 130, "y": 100, "w": 170, "h": 64, "sys": "climate", "detail": "Experiments on pushing at entrances and force sensors on bodies; how forces spread at extreme density."}, {"id": "psy", "label": "Psychology and culture", "sub": "identity, norms", "x": 130, "y": 260, "w": 170, "h": 64, "sys": "economy", "detail": "Social identity, groups, culture and norms in movement models (Sieben et al. 2017; Drury et al. 2009)."}, {"id": "ai", "label": "AI for monitoring", "sub": "counting, tracking, privacy", "x": 130, "y": 420, "w": 170, "h": 64, "sys": "water", "detail": "Reliable real-time counting and tracking across cameras and cultures, with privacy protection."}, {"id": "twin", "label": "Digital twins", "sub": "forecast early", "x": 450, "y": 420, "w": 170, "h": 64, "sys": "neutral", "detail": "Models in step with live data, forecasting danger minutes ahead."}, {"id": "heat", "label": "Heat and health", "sub": "vulnerable crowds", "x": 770, "y": 420, "w": 170, "h": 64, "sys": "economy", "detail": "Interactions of heat, age, health and crowding at mass gatherings such as the Hajj."}, {"id": "study", "label": "Your study", "sub": "question, data, model", "x": 450, "y": 210, "w": 170, "h": 64, "sys": "neutral", "detail": "Your research question, built in modules 3.1 to 3.7."}, {"id": "rep", "label": "Reporting", "sub": "uncertainty and limits", "x": 770, "y": 210, "w": 170, "h": 64, "sys": "policy", "detail": "Ranges, sensitivity, model limits, and a clear message for decision makers."}], "edges": [{"from": "push", "to": "study", "label": ""}, {"from": "psy", "to": "study", "label": ""}, {"from": "ai", "to": "study", "label": ""}, {"from": "twin", "to": "study", "label": ""}, {"from": "heat", "to": "study", "label": ""}, {"from": "study", "to": "rep", "label": "write up"}], "tour": [{"focus": ["push", "psy"], "text": "Two fronts: the physics of pushing and forces, and the psychology of crowds."}, {"focus": ["ai", "twin"], "text": "Two more: AI for monitoring, and digital twins that forecast."}, {"focus": ["heat"], "text": "And heat and health at mass gatherings."}, {"focus": ["study"], "text": "Your study draws on these fronts.", "edges": [["push", "study"], ["psy", "study"], ["ai", "study"], ["twin", "study"], ["heat", "study"]]}, {"focus": ["rep"], "text": "Finally, report it honestly, with uncertainty and limits.", "edges": [["study", "rep"]]}]}};
